const SEQ=[3,0,4,1,2,4,2,0,3,1,2,4,0,3,1];let sq=0;
const COMB=(L)=>{const r=[];for(let m=1;m<8;m++){const x=L.filter((_,i)=>m>>i&1);r.push(x)}return r.sort((p,q)=>p.length-q.length||(p.join()<q.join()?-1:1)).map(x=>x.join(', '))};
const SETS=[['ㄱ','ㄴ','ㄷ'],['갑','을','병']];
